{
  "name": "@foresttruong/opencode-copy-slash",
  "version": "1.0.1",
  "description": "OpenCode plugin that adds /copy command to copy last assistant message to clipboard",
  "type": "module",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "copy",
    "clipboard",
    "slash-command"
  ],
  "main": "./.opencode/plugins/copy.js",
  "exports": {
    ".": "./.opencode/plugins/copy.js"
  },
  "files": [
    ".opencode/",
    "commands/"
  ],
  "peerDependencies": {
    "@opencode-ai/sdk": ">=1.0.0"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/foresttruong/plugin-copy-opencode.git"
  }
}
